package com.tlenparty.algolingo.lesson

import java.io.ByteArrayOutputStream
import java.io.File
import java.io.PrintStream
import java.net.URLClassLoader
import java.nio.file.Files
import kotlinx.serialization.Serializable
import kotlinx.serialization.json.Json
import org.jetbrains.kotlin.cli.common.ExitCode
import org.jetbrains.kotlin.cli.jvm.K2JVMCompiler
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.fail

/**
 * Proves every wrong-chip claim (JVM only): each program from wrong_variants.json (generated by
 * tools/gen_content.py) is compiled with the embedded compiler and run; `V.kinds()` reports which
 * examples broke and how. Observed kinds: compile | wrong | crash | hang; empty = runs clean.
 * All mismatches go into one message and build/reports/wrong-chips.txt.
 */
class WrongChipsTest {
    @Serializable
    data class Claim(val bullet: String, val scope: String, val tags: List<String>)

    @Serializable
    data class Entry(
        val id: String,
        val ids: List<String>,
        val lesson: String,
        val label: String,
        val claims: List<Claim>,
        val pending: Boolean,
        val source: String,
    )

    private val cp = listOf(loc(Unit::class.java), loc(Class.forName("kotlin.test.AssertionsKt")))
        .joinToString(File.pathSeparator)

    private fun loc(c: Class<*>) = File(c.protectionDomain.codeSource.location.toURI()).path

    private fun observe(source: String): Set<String> {
        val dir = Files.createTempDirectory("wv").toFile()
        try {
            val src = File(dir, "V.kt").also { it.writeText(source) }
            val out = File(dir, "out")
            val code = K2JVMCompiler().exec(
                PrintStream(ByteArrayOutputStream()), "-no-stdlib", "-no-reflect", "-nowarn",
                "-cp", cp, "-d", out.path, src.path,
            )
            if (code != ExitCode.OK) return setOf("compile")
            URLClassLoader(arrayOf(out.toURI().toURL()), javaClass.classLoader).use { cl ->
                val c = cl.loadClass("V")
                val kinds = c.getMethod("kinds").invoke(c.getField("INSTANCE").get(null)) as String
                return kinds.split(',').filter { it.isNotEmpty() }.toSet()
            }
        } finally {
            dir.deleteRecursively()
        }
    }

    /** A failure line plus the entry ids it is attributed to (any pending one parks it). */
    private class Finding(val line: String, val entries: Set<String>)

    @Test
    fun everyWrongChipBreaksAsTagged() {
        val entries = Json { ignoreUnknownKeys = true }
            .decodeFromString<List<Entry>>(File("src/androidHostTest/resources/wrong_variants.json").readText())
        val observed = entries.associate { it.id to observe(it.source) }
        val findings = mutableListOf<Finding>()

        for (e in entries) {
            val o = observed.getValue(e.id)
            if (o.isEmpty()) findings += Finding("${e.id} runs clean (false wrong?) [${e.label}]", setOf(e.id))
            for (c in e.claims.filter { it.scope == "hole" }) {
                val missing = c.tags - o
                if (missing.isNotEmpty()) findings += Finding(
                    "${e.id} ${c.bullet}: expected ${c.tags} observed ${o.sorted()} (missing $missing)", setOf(e.id),
                )
            }
        }
        // chip scope: the reason holds for the chip in any hole of the exercise, so tags must be in the union
        val groups = entries.flatMap { e -> e.claims.filter { it.scope == "chip" }.map { it to e } }
            .groupBy({ it.first.bullet }, { it.second })
        for ((bullet, group) in groups) {
            val tags = entries.flatMap { it.claims }.first { it.bullet == bullet && it.scope == "chip" }.tags
            val union = group.flatMap { observed.getValue(it.id) }.toSet()
            val missing = tags - union
            if (missing.isNotEmpty()) findings += Finding(
                "${group.joinToString("+") { it.id }} $bullet: expected $tags observed ${union.sorted()} (missing $missing)",
                group.map { it.id }.toSet(),
            )
        }

        val pending = entries.filter { it.pending }.map { it.id }.toSet()
        val failing = findings.filter { f -> f.entries.none { it in pending } }.map { it.line }
        val parked = findings.filter { f -> f.entries.any { it in pending } }.map { "PENDING " + it.line }
        val stale = (pending - findings.flatMap { it.entries }.toSet()).map { "$it stale pending (now passes, remove from pending.txt)" }

        val report = File("build/reports/wrong-chips.txt")
        report.parentFile.mkdirs()
        report.writeText(
            (listOf("# ${entries.size} programs, ${findings.size} findings, ${pending.size} pending") +
                failing + stale + parked + entries.map { "observed ${it.id}: ${observed.getValue(it.id).sorted()}" })
                .joinToString("\n", postfix = "\n"),
        )
        val bad = failing + stale
        if (bad.isNotEmpty()) fail("${bad.size} wrong-chip mismatches (see ${report.path}):\n" + bad.joinToString("\n"))
    }

    @Test
    fun classifierSanity() {
        val clean = """
            object V {
                fun kinds(): String = ""
            }
        """.trimIndent()
        assertEquals(emptySet(), observe(clean))
        // uses kotlin.test so a broken classpath shows up here, not as 248 "compile" verdicts
        val wrong = """
            import kotlin.test.*
            object V {
                fun kinds(): String = try { assertEquals(1, 2); "" } catch (e: AssertionError) { "wrong" }
            }
        """.trimIndent()
        assertEquals(setOf("wrong"), observe(wrong))
        assertEquals(setOf("compile"), observe("object V { fun kinds(): String = 1 }"))
    }
}
